1	import React, { useEffect, useState } from 'react';
2	import { ProjectBudget } from './ProjectBudget';
3	import { ProjectInvoices } from './ProjectInvoices';
4	import { ProjectNotes } from './ProjectNotes';
5	import { ProjectTags } from './ProjectTags';
6	import { ProjectTasks } from './ProjectTasks';
7	
8	// The projects feature owns its own state, data loading and layout (no global store). It lists every
9	// project with its client's NAME (a cross-entity join surfaced in the UI) and adds a new project by
10	// name + chosen client. The client select's option values are client ids.
11	type Project = {
12	  id: number;
13	  name: string;
14	  clientId: number;
15	  clientName: string;
16	  archived: boolean;
17	  status: string;
18	  tagIds: number[];
19	  code: string;
20	};
21	type Client = { id: number; name: string; email: string };
22	type Tag = { id: number; name: string };
23	
24	// A project is marked active, on hold or finished; the owner picks when creating one.
25	const PROJECT_STATUSES = ['ACTIVE', 'ON_HOLD', 'FINISHED'];
26	
27	export function ProjectsPage() {
28	  const [projects, setProjects] = useState<Project[]>([]);
29	  const [clients, setClients] = useState<Client[]>([]);
30	  const [tags, setTags] = useState<Tag[]>([]);
31	  const [name, setName] = useState('');
32	  const [clientId, setClientId] = useState('');
33	  const [status, setStatus] = useState('ACTIVE');
34	  const [budget, setBudget] = useState('');
35	  const [code, setCode] = useState('');
36	  const [codeError, setCodeError] = useState('');
37	  const [openProjectId, setOpenProjectId] = useState<number | null>(null);
38	  const [showArchived, setShowArchived] = useState(false);
39	  const [filterTagId, setFilterTagId] = useState('');
40	  const [filterStatus, setFilterStatus] = useState('');
41	
42	  async function load() {
43	    const [pRes, cRes, tRes] = await Promise.all([
44	      fetch('/api/projects'),
45	      fetch('/api/clients'),
46	      fetch('/api/tags'),
47	    ]);
48	    setProjects(await pRes.json());
49	    setClients(await cRes.json());
50	    setTags(await tRes.json());
51	  }
52	
53	  useEffect(() => {
54	    void load();
55	  }, []);
56	
57	  async function remove(projectId: number) {
58	    const res = await fetch(`/api/projects/${projectId}`, { method: 'DELETE' });
59	    if (!res.ok) {
60	      return;
61	    }
62	    if (openProjectId === projectId) {
63	      setOpenProjectId(null);
64	    }
65	    await load();
66	  }
67	
68	  // Archiving tucks a project away: it drops off the list unless archived ones are revealed, and is
69	  // retained (the server keeps the row, just flagged). Delete still removes a project outright.
70	  async function archive(projectId: number) {
71	    const res = await fetch(`/api/projects/${projectId}/archive`, { method: 'POST' });
72	    if (!res.ok) {
73	      return;
74	    }
75	    if (openProjectId === projectId) {
76	      setOpenProjectId(null);
77	    }
78	    await load();
79	  }
80	
81	  async function onSubmit(e: React.FormEvent) {
82	    e.preventDefault();
83	
84	    // Every job needs a reference code — block the save and surface the error if it is missing, so
85	    // no row is created.
86	    if (code.trim() === '') {
87	      setCodeError('A reference code is required');
88	      return;
89	    }
90	    setCodeError('');
91	
92	    const res = await fetch('/api/projects', {
93	      method: 'POST',
94	      headers: { 'Content-Type': 'application/json' },
95	      body: JSON.stringify({
96	        name,
97	        clientId: Number(clientId),
98	        status,
99	        budget: budget === '' ? 0 : Number(budget),
100	        code: code.trim(),
101	      }),
102	    });
103	    if (!res.ok) {
104	      // A 409 means the code is already taken by another job; anything else is a bad code.
105	      setCodeError(
106	        res.status === 409
107	          ? 'A job with this code already exists'
108	          : 'A reference code is required',
109	      );
110	      return;
111	    }
112	    setName('');
113	    setClientId('');
114	    setStatus('ACTIVE');
115	    setBudget('');
116	    setCode('');
117	    await load();
118	  }
119	
120	  return (
121	    <section data-testid="projects-section">
122	      <h1>Jobs</h1>
123	
124	      <form data-testid="project-form" onSubmit={onSubmit}>
125	        <input
126	          data-testid="project-form-name"
127	          placeholder="Job name"
128	          value={name}
129	          onChange={(e) => setName(e.target.value)}
130	        />
131	        <select
132	          data-testid="project-form-client"
133	          value={clientId}
134	          onChange={(e) => setClientId(e.target.value)}
135	        >
136	          <option value="">Select a client</option>
137	          {clients.map((c) => (
138	            <option key={c.id} value={c.id}>
139	              {c.name}
140	            </option>
141	          ))}
142	        </select>
143	        <select
144	          data-testid="project-form-status"
145	          value={status}
146	          onChange={(e) => setStatus(e.target.value)}
147	        >
148	          {PROJECT_STATUSES.map((s) => (
149	            <option key={s} value={s}>
150	              {s}
151	            </option>
152	          ))}
153	        </select>
154	        <input
155	          data-testid="project-form-budget"
156	          placeholder="Budget"
157	          value={budget}
158	          onChange={(e) => setBudget(e.target.value)}
159	        />
160	        <input
161	          data-testid="project-form-code"
162	          placeholder="Reference code"
163	          value={code}
164	          onChange={(e) => setCode(e.target.value)}
165	        />
166	        {codeError && (
167	          <p data-testid="project-form-code-error" role="alert">
168	            {codeError}
169	          </p>
170	        )}
171	        <button type="submit" data-testid="project-form-submit">
172	          Add job
173	        </button>
174	      </form>
175	
176	      <button
177	        type="button"
178	        data-testid="projects-show-archived"
179	        aria-pressed={showArchived}
180	        onClick={() => setShowArchived((s) => !s)}
181	      >
182	        {showArchived ? 'Hide archived' : 'Show archived'}
183	      </button>
184	
185	      <select
186	        data-testid="project-tag-filter"
187	        value={filterTagId}
188	        onChange={(e) => setFilterTagId(e.target.value)}
189	      >
190	        <option value="">All tags</option>
191	        {tags.map((t) => (
192	          <option key={t.id} value={t.id}>
193	            {t.name}
194	          </option>
195	        ))}
196	      </select>
197	
198	      <select
199	        data-testid="project-status-filter"
200	        value={filterStatus}
201	        onChange={(e) => setFilterStatus(e.target.value)}
202	      >
203	        <option value="">All statuses</option>
204	        {PROJECT_STATUSES.map((s) => (
205	          <option key={s} value={s}>
206	            {s}
207	          </option>
208	        ))}
209	      </select>
210	
211	      {(() => {
212	        const byArchived = showArchived ? projects : projects.filter((p) => !p.archived);
213	        const byTag = filterTagId
214	          ? byArchived.filter((p) => (p.tagIds ?? []).includes(Number(filterTagId)))
215	          : byArchived;
216	        const visible = filterStatus
217	          ? byTag.filter((p) => p.status === filterStatus)
218	          : byTag;
219	        return visible.length === 0 ? (
220	          <p data-testid="projects-empty">No jobs yet.</p>
221	        ) : (
222	        <table data-testid="projects-table">
223	          <thead>
224	            <tr>
225	              <th>Code</th>
226	              <th>Name</th>
227	              <th>Client</th>
228	              <th>Status</th>
229	            </tr>
