  // Lets the page react to an invoice being opened/closed (e.g. the project's own notes step aside
  // for the opened invoice's notes). Fired with the opened invoice id, or null when none is open.
  onOpenChange?: (invoiceId: number | null) => void;
}) {
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [amount, setAmount] = useState('');
  const [error, setError] = useState('');
  const [sort, setSort] = useState<'id' | 'due'>('id');
  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
  const [openStatus, setOpenStatus] = useState('');
  const [openDiscountPct, setOpenDiscountPct] = useState(0);
  const [openTaxPct, setOpenTaxPct] = useState(0);

  async function load(order: 'id' | 'due' = sort) {
    const res = await fetch(`/api/projects/${projectId}/invoices?sort=${order}`);
    setInvoices(await res.json());
  }

  // The opened invoice's status is derived from its payments, so re-read it on open and whenever a
  // payment is recorded against it.
  async function loadInvoice(invoiceId: number) {
    const res = await fetch(`/api/invoices/${invoiceId}`);
    if (!res.ok) {
      return;
    }
    const inv: Invoice = await res.json();
    setOpenStatus(inv.status);
    setOpenDiscountPct(Number(inv.discountPct ?? 0));
    setOpenTaxPct(Number(inv.taxPct ?? 0));
  }

  useEffect(() => {
    void load();
  }, [projectId]);

  useEffect(() => {
    if (openInvoiceId !== null) {
      void loadInvoice(openInvoiceId);
    }
    onOpenChange?.(openInvoiceId);
  }, [openInvoiceId]);

  async function sortByDue() {
    setSort('due');
    await load('due');
  }

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    const value = Number(amount);
    if (!(value > 0)) {
      setError('Amount must be greater than zero');
      return;
    }
    setError('');
    const res = await fetch(`/api/projects/${projectId}/invoices`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ amount: Number(amount) }),
    });
    if (!res.ok) {
      return;
    }
    setAmount('');
    await load();
  }

  async function send(invoiceId: number) {
    const res = await fetch(`/api/invoices/${invoiceId}/send`, { method: 'POST' });
    if (!res.ok) {
      return;
    }
    await load();
  }

  // Cancel (void) an invoice sent by mistake: it reads VOID and stops counting toward what is owed.
  async function cancel(invoiceId: number) {
    const res = await fetch(`/api/invoices/${invoiceId}/void`, { method: 'POST' });
    if (!res.ok) {
      return;
    }
    await load();
  }

  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);

  if (openInvoiceId !== null) {
    return (
      <section data-testid="project-invoices">
        <h2>Invoices</h2>
        <p>
          Status: <span data-testid="invoice-status">{openStatus}</span>
        </p>
        <InvoiceLineItems
          invoiceId={openInvoiceId}
          discountPct={openDiscountPct}
          taxPct={openTaxPct}
          onClose={() => {
            setOpenInvoiceId(null);
            void load();
          }}
        />
        <InvoicePayments
          invoiceId={openInvoiceId}
          onRecorded={() => void loadInvoice(openInvoiceId)}
        />
      </section>
    );
  }

  return (
    <section data-testid="project-invoices">
      <h2>Invoices</h2>

      <form data-testid="invoice-form" onSubmit={onSubmit}>
        <input
          data-testid="invoice-form-amount"
          placeholder="Amount"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        />
        <button type="submit" data-testid="invoice-form-submit">
          Add invoice
        </button>
        {error ? (
          <p data-testid="invoice-form-amount-error" role="alert">
            {error}
          </p>
        ) : null}
      </form>

      <button type="button" data-testid="invoice-sort-due" onClick={() => void sortByDue()}>
        Sort by due date
      </button>

      <table data-testid="project-invoices-table">
        <thead>
          <tr>
            <th>Amount</th>
            <th>Due</th>
            <th>Status</th>
            <th>Issued</th>
            <th>Due</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {invoices.map((inv) => (
            <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
              <td data-testid="invoice-amount">{formatAmount(inv.amount)}</td>
              <td data-testid="invoice-due-amount">{formatAmount(inv.due)}</td>
              <td data-testid="invoice-status">{inv.status}</td>
              <td data-testid="invoice-issued">{inv.issuedDate ?? ''}</td>
              <td data-testid="invoice-due">{inv.dueDate ?? ''}</td>
              <td>
                <button
                  type="button"
                  data-testid={`invoice-open-${inv.id}`}
                  onClick={() => setOpenInvoiceId(inv.id)}
                >
                  Open
                </button>
                {inv.status === 'DRAFT' ? (
                  <button
                    type="button"
                    data-testid={`invoice-send-${inv.id}`}
                    onClick={() => void send(inv.id)}
                  >
                    Send
                  </button>
                ) : null}
                {inv.status === 'SENT' ? (
                  <button
                    type="button"
                    data-testid={`invoice-cancel-${inv.id}`}
                    onClick={() => void cancel(inv.id)}
                  >
                    Cancel
                  </button>
                ) : null}
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <td data-testid="project-invoices-total">{formatAmount(total)}</td>
          </tr>
        </tfoot>
      </table>
    </section>
  );
}

